# Generated by build.py from recipe.yml for recipe smtp-survive-a-temporary-rcpt-failure. Do not edit.
set -e
cd "$(dirname "$0")"
cat > order.eml <<'EOF'
From: app@example.com
To: ann@example.com
Subject: Order 1042 has shipped

Your order is on its way.
EOF
cat > send-retrying.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Sends one message with curl, retrying only a temporary (4xx) refusal, at most <tries> tries in all.
# Usage: sh send-retrying.sh <tries> <curl arguments...>
tries=$1
shift
while :; do
  code=$(curl -s -w "%{response_code}" "$@")
  status=$?
  if [ "$status" -eq 0 ]; then
    echo "sent: $code"
    exit 0
  fi
  tries=$((tries - 1))
  case $code in
    4??)
      if [ "$tries" -gt 0 ]; then
        echo "temporary: $code, retrying"
        sleep 1
        continue
      fi ;;
  esac
  echo "gave up: $code"
  exit "$status"
done
EOF
surl -v --log-file surl.log --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --fault "error;scheme=smtp;command=RCPT;reply=451 4.3.0 try later;times=1" smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
sh send-retrying.sh 3 --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T order.eml smtp://127.0.0.1:8080/example.com && curl -s -u ann@example.com:annpass -X "STATUS INBOX (MESSAGES)" imap://127.0.0.1:8081/
kill $(jobs -p)
